#include <cstddef>
#include <functional>
#include <unordered_map>

struct Cell {
    int row;
    int col;
    bool operator==(const Cell&) const = default;
};

template <>
struct std::hash<Cell> {
    std::size_t operator()(const Cell& c) const noexcept {
        std::size_t h = std::hash<int>{}(c.row);
        h ^= std::hash<int>{}(c.col) + 0x9e3779b9 + (h << 6) + (h >> 2);
        return h;
    }
};
